import type { StrumSound } from './instrument-sounds.ts';
import type { StrumDirection, StrumStep } from './patterns.ts';

/**
 * How one step of a pattern becomes the notes a player sounds, and how a
 * chord card rolls its chord — the performance, before any sound is made
 * (`StrumSoundEngine.ts` plays it). Each instrument plays its own way
 * (`technique` in `instrument-sounds.ts`):
 *
 * - **Strum** (guitar, ukuleles). A down stroke crosses the strings in string
 *   order, lowest string first; an up stroke comes back from the highest and
 *   catches only the top `upShare` of them. A light down stroke — on an `e` or
 *   `a` sixteenth — skips a guitar's lowest string. Each string sounds
 *   `noteGap` after the one before: a little slower on a soft stroke, quicker
 *   on an up stroke. The strings the pick meets last sound a little softer.
 * - **Keys** (piano). A down stroke strikes the whole voicing, an up stroke
 *   the voicing without its lowest note — the right hand alone — a little
 *   softer. The notes land within a few milliseconds of each other.
 * - **Pluck** (bass). A down stroke plucks the voicing's lowest note, its
 *   root; an up stroke its highest, the octave. A bass sounds one note at a
 *   time.
 *
 * A stroke's force is its step's velocity (`getStepVelocity`). A player is
 * human: each stroke lands up to `humanize.timing` off the grid, and each note
 * wanders up to `humanize.velocity` in force and `humanize.detune` in tuning.
 * `random` draws those; one that always returns `0.5` plays exactly.
 */

export interface PlannedNote {
  pitch: number;
  /** Seconds after the stroke lands — after the roll starts, for a roll. */
  offset: number;
  /** Loudness, 0–1. */
  velocity: number;
  /**
   * The string (a piano's key) that sounds it — its index in the voicing. A
   * new note on a string damps the one ringing there; a bass has one.
   */
  slot: number;
  /** Cents off pitch. */
  detune: number;
  /** Stereo position, −1 (left) to 1 (right). */
  pan: number;
}

export interface StrokePlan {
  direction: StrumDirection;
  /** Seconds the stroke lands after its step; negative when early. */
  shift: number;
  /** The notes in the order the stroke meets them. */
  notes: PlannedNote[];
}

/** How loud a chord card's roll is. */
export const CHORD_ROLL_VELOCITY = 0.7;
/** A down stroke this soft or softer skips the lowest string. */
const LIGHT_STROKE_VELOCITY = 0.6;
/** The fewest strings a stroke skipping the lowest one leaves sounding. */
const LIGHT_STROKE_MIN_STRINGS = 4;
/** An up stroke crosses the strings this much faster than a down stroke. */
const UP_STROKE_SPEED = 0.85;
/** How much softer the last string a stroke meets is than the first. */
const DOWN_STROKE_TAPER = 0.12;
const UP_STROKE_TAPER = 0.25;
/** A piano's right hand alone, on an up stroke. */
const RIGHT_HAND_FORCE = 0.9;
/** How far each gap between strings, or roll notes, wanders (a share). */
const GAP_WANDER = 0.2;
/** Where a piano's pan is centred, and the notes either side reaching full width. */
const PIANO_PAN_CENTRE = 60;
const PIANO_PAN_SPAN = 30;
const QUIETEST_NOTE = 0.05;

function clamp(value: number, low: number, high: number) {
  return Math.min(high, Math.max(low, value));
}

function range(from: number, to: number) {
  return Array.from({ length: Math.max(0, to - from) }, (_, i) => from + i);
}

/** A draw between `-amount` and `amount`. */
function wander(random: () => number, amount: number) {
  return (random() * 2 - 1) * amount;
}

/**
 * The voicing's notes a stroke sounds, as indexes into it, in the order the
 * stroke meets them.
 */
export function getStrokeStrings(
  count: number,
  direction: StrumDirection,
  velocity: number,
  sound: StrumSound,
  random: () => number,
): number[] {
  if (!count) {
    return [];
  }

  switch (sound.technique) {
    case 'keys':
      return direction === 'up' && count >= 3
        ? range(1, count)
        : range(0, count);
    case 'pluck':
      return [direction === 'up' ? count - 1 : 0];
    default: {
      if (direction === 'down') {
        const skip =
          velocity <= LIGHT_STROKE_VELOCITY && count > LIGHT_STROKE_MIN_STRINGS
            ? 1
            : 0;

        return range(skip, count);
      }

      const caught = clamp(
        Math.round(count * sound.upShare + (random() - 0.5)),
        Math.min(2, count),
        count,
      );

      return range(count - caught, count).reverse();
    }
  }
}

function getPan(sound: StrumSound, slot: number, count: number, pitch: number) {
  switch (sound.technique) {
    case 'keys':
      return (
        clamp((pitch - PIANO_PAN_CENTRE) / PIANO_PAN_SPAN, -1, 1) * sound.width
      );
    case 'pluck':
      return 0;
    default:
      return count > 1 ? sound.width * ((2 * slot) / (count - 1) - 1) : 0;
  }
}

/** The notes of step `step`'s stroke, or `null` for a rest or no chord. */
export function planStroke(
  chord: readonly number[],
  step: StrumStep | null | undefined,
  sound: StrumSound,
  random: () => number = Math.random,
): StrokePlan | null {
  if (!step || !chord.length) {
    return null;
  }

  const force = step.velocity;
  const up = step.direction === 'up';
  const strings = getStrokeStrings(
    chord.length,
    step.direction,
    force,
    sound,
    random,
  );
  const speed = (1.35 - 0.5 * force) * (up ? UP_STROKE_SPEED : 1);
  const taper = up ? UP_STROKE_TAPER : DOWN_STROKE_TAPER;
  const rightHand = up && strings.length < chord.length ? RIGHT_HAND_FORCE : 1;
  let offset = 0;

  const notes = strings.map((index, order): PlannedNote => {
    if (order > 0) {
      offset +=
        sound.technique === 'keys'
          ? 0
          : sound.noteGap * speed * (1 + wander(random, GAP_WANDER));
    }

    const pitch = chord[index];
    const reach = strings.length > 1 ? order / (strings.length - 1) : 0;
    let velocity: number;
    let noteOffset = offset;

    switch (sound.technique) {
      case 'keys':
        velocity = force * rightHand;
        noteOffset = order > 0 ? random() * 2 * sound.noteGap : 0;
        break;
      case 'pluck':
        velocity = force;
        break;
      default:
        velocity = force * (1 - taper * reach);
    }

    return {
      pitch,
      offset: noteOffset,
      velocity: clamp(
        velocity * (1 + wander(random, sound.humanize.velocity)),
        QUIETEST_NOTE,
        1,
      ),
      slot: sound.technique === 'pluck' ? 0 : index,
      detune: wander(random, sound.humanize.detune),
      pan: getPan(sound, index, chord.length, pitch),
    };
  });

  return {
    direction: step.direction,
    shift: wander(random, sound.humanize.timing),
    notes,
  };
}

/**
 * A chord card's play: the notes one after another in the order given — from
 * the first string listed — `rollGap` apart, each on its own string.
 */
export function planChordRoll(
  midi: readonly number[],
  sound: StrumSound,
  random: () => number = Math.random,
): PlannedNote[] {
  let offset = 0;

  return midi.map((pitch, index) => {
    if (index > 0) {
      offset += sound.rollGap * (1 + wander(random, GAP_WANDER));
    }

    return {
      pitch,
      offset,
      velocity: clamp(
        CHORD_ROLL_VELOCITY * (1 + wander(random, sound.humanize.velocity)),
        QUIETEST_NOTE,
        1,
      ),
      slot: index,
      detune: wander(random, sound.humanize.detune),
      pan: getPan(sound, index, midi.length, pitch),
    };
  });
}

/** Seconds from a roll's first note to its last, before any wandering. */
export function getChordRollSeconds(sound: StrumSound, noteCount: number) {
  return Math.max(0, noteCount - 1) * sound.rollGap;
}
