/**
 * The playground's markup. Every element the code reaches carries a
 * `data-olp-ref`; ids exist only for label/ARIA links and are prefixed per
 * instance, so two playgrounds can share a page.
 */
export function createPlaygroundMarkup(prefix: string): string {
  const id = (name: string) => `${prefix}-${name}`;

  return `
    <div class="page">
      <header class="page-header">
        <div>
          <h1>Strum Player</h1>
          <p>
            Hear an Open Lyric song's strumming patterns — and every chord Open
            Lyric offers — on guitars, keyboards, ukuleles and basses. Patterns
            are written in the notation's Strumming Patterns syntax.
          </p>
        </div>
      </header>

      <section class="panel song-bar" aria-label="Song">
        <label class="song-field">Key <select data-olp-ref="key"></select></label>
        <label class="song-field">Time <select data-olp-ref="time"></select></label>
        <div class="song-field song-field--tempo">
          <label for="${id('tempo')}">Tempo</label>
          <input data-olp-ref="tempoRange" type="range" min="20" max="300" step="1" aria-label="Tempo slider" />
          <input data-olp-ref="tempo" id="${id('tempo')}" type="number" min="20" max="300" step="1" inputmode="numeric" />
          <span>bpm</span>
        </div>
      </section>

      <div class="layout">
        <section class="panel instruments" aria-labelledby="${id('instruments')}">
          <h2 id="${id('instruments')}">Instruments</h2>
          <div data-olp-ref="instruments" class="instrument-list" role="radiogroup" aria-labelledby="${id('instruments')}"></div>
          <div data-olp-ref="voicing" class="voicing" aria-live="polite"></div>
        </section>

        <section class="panel patterns" aria-labelledby="${id('patterns')}">
          <div class="patterns__header">
            <h2 id="${id('patterns')}">Patterns</h2>
            <button data-olp-ref="restore" class="text-button" type="button">Restore example patterns</button>
          </div>
          <div data-olp-ref="patterns" class="pattern-list"></div>
          <p data-olp-ref="patternsEmpty" class="pattern-list__empty" hidden>No patterns — add one below.</p>
          <details class="add-patterns">
            <summary>Add patterns</summary>
            <p>
              Open Lyric notation, one pattern per line — <code>d</code> down,
              <code>u</code> up, <code>x</code> alternating, <code>-</code> rest,
              <code>|</code> between groups, and a <code>// label</code> line
              above to name it. Each character is one sixteenth note.
            </p>
            <label class="visually-hidden" for="${id('input')}">Patterns to add</label>
            <textarea data-olp-ref="input" id="${id('input')}" spellcheck="false" placeholder="// Island strum&#10;d-d-u-u-d-u-d-u-"></textarea>
            <div class="add-patterns__actions">
              <button data-olp-ref="add" class="primary-button" type="button">Add</button>
              <span data-olp-ref="addError" class="add-patterns__error" role="alert"></span>
            </div>
          </details>
        </section>
      </div>

      <p data-olp-ref="status" class="status" role="status" aria-live="polite"></p>

      <section class="panel chords" aria-labelledby="${id('chords')}">
        <div class="chords__header">
          <h2 id="${id('chords')}">Chords</h2>
          <p data-olp-ref="chordsSummary" class="chords__summary"></p>
        </div>
        <p class="chords__intro">
          Every chord Open Lyric offers. Point at one for its voicing on the
          selected instrument, then press the play button on the card, or the
          chord itself, to hear it rolled from the lowest string up.
        </p>
        <div data-olp-ref="chords" class="chord-groups"></div>
      </section>

      <details class="panel notes">
        <summary>How it plays</summary>
        <ul>
          <li>
            Sound: FluidR3 soundfonts, served with this player and heard in a
            small room — nylon guitar for the classical guitar and both
            ukuleles (General MIDI has no ukulele), and an electric bass for
            Bass, whose line carries on small speakers; the Upright Bass is
            darker, as the instrument is.
          </li>
          <li>
            Notes: a pattern strums the song key's chord as the instrument
            voices it, in standard tuning — the same voicing the chord's card
            shows below.
          </li>
          <li>
            Voicings: guitar and ukulele shapes come from the chords-db
            database the editor's chord popup uses, or are computed from the
            chord's notes when a computed shape is clearly easier; baritone
            ukulele shapes are computed. On guitar and baritone the lowest note
            is always the chord's bass. Bass plays the root with its fifth and
            octave; piano stacks the chord from its root in octave 3.
          </li>
          <li>
            Strokes: each character of a pattern is a sixteenth note at the
            song's tempo. Guitar and ukuleles strum in string order — down from
            the lowest string, up from the highest, catching only the top
            strings. The keyboards play the chord, the right hand alone on an
            up stroke, and the organ holds it; the basses pluck the root on a
            down stroke and the octave on an up stroke. A string rings until it is struck again; stopping a
            pattern damps the strings still ringing.
          </li>
          <li>
            Feel: the bar's first beat is loudest, then the other beats, the
            off-beats, and the sixteenths in between. A soft stroke sounds
            darker than a hard one, and each lands a little differently, as a
            player's would.
          </li>
          <li>
            Chord cards roll the chord string by string, and bass plucks each
            note in turn. A name Open Lyric's chord theory can't read (Cmaj2,
            Am4, …) has nothing to play.
          </li>
        </ul>
      </details>
    </div>
  `;
}
